import rbd,time
def parent(image):
    try:return list(image.parent_info())
    except rbd.ImageNotFound:return None
def inventory(api,ioctxs,scope_complete):
    images={}
    for pool,io in sorted(ioctxs.items()):
        for name in sorted(api.list(io)):
            with rbd.Image(io,name)as image:
                snapshots={}
                for row in image.list_snaps():
                    snap=row['name']
                    with rbd.Image(io,name,snapshot=snap,read_only=True)as view:
                        snapshots[snap]={'protected':image.is_protected_snap(snap),'parent':parent(view),'children':sorted(p+'/'+n for p,n in view.list_children())}
                images[pool+'/'+name]={'size_bytes':image.size(),'parent':parent(image),'snapshots':snapshots}
    return {'scope_pools':sorted(ioctxs),'scope_complete':scope_complete,'images':images}
def may_delete(graph,pool,image,snapshot):
    if graph['scope_complete']is not True:return False
    target=[pool,image,snapshot];node=graph['images'].get(pool+'/'+image);snap=node['snapshots'].get(snapshot)if node else None
    if snap is None or snap['children']:return False
    for row in graph['images'].values():
        if row['parent']==target or any(s['parent']==target for s in row['snapshots'].values()):return False
    return True
def flatten(image,observe,approved_free_data_bytes,reserve_bytes,expected_sha256):
    before=observe();needed=max(0,before['size_bytes']-before['owned_data_bytes'])if before['parent']is not None else 0
    if approved_free_data_bytes<needed+reserve_bytes:raise ValueError('flatten exceeds approved capacity envelope')
    started=time.monotonic_ns()
    if before['parent']is not None:image.flatten()
    after=observe()
    if after['parent']is not None or after['sha256']!=expected_sha256:raise ValueError('dependency or content not verified')
    return {'before':before,'after':after,'estimated_additional_data_bytes':needed,'actual_growth_data_bytes':after['owned_data_bytes']-before['owned_data_bytes'],'copy_read_budget_bytes':needed,'copy_write_budget_bytes':needed,'observed_osd_in_bytes_delta':after['perf']['op_in_bytes']-before['perf']['op_in_bytes'],'observed_osd_out_bytes_delta':after['perf']['op_out_bytes']-before['perf']['op_out_bytes'],'elapsed_ns':time.monotonic_ns()-started,'concurrent_flattens_limit':1,'retain_parent_until':'all_children_detached_and_data_verified'}

