import hashlib,json,rbd
def parent(image):
    try:return list(image.parent_info())
    except rbd.ImageNotFound:return None
def digest(image):
    h=hashlib.sha256();size=image.size()
    for offset in range(0,size,4*1024*1024):h.update(image.read(offset,min(4*1024*1024,size-offset)))
    return h.hexdigest()
def data_objects(io,image):
    prefix='rbd_data.'+image.id()+'.';return {obj.key:io.stat(obj.key)[0]for obj in io.list_objects()if obj.key.startswith(prefix)}
def observe(cluster,io,image,command):
    size=image.size();owned=sum(data_objects(io,image).values());association=parent(image);sha=digest(image)
    raw=json.loads(command('ceph','--admin-daemon',cluster.root/'osd.0.asok','perf','dump'));perf=raw['osd']
    return {'size_bytes':size,'owned_data_bytes':owned,'parent':association,'sha256':sha,'perf':{name:perf[name]for name in ('op_in_bytes','op_out_bytes','stat_bytes_avail')}}

